mapper.select:
SELECT s.drugs_name AS drugsName, COALESCE(SUM(s.num), 0) AS qty, COALESCE(SUM(COALESCE(s.price, 0) * COALESCE(s.num, 0)), 0) AS amount FROM sale s
s.drugs_name IS NOT NULL
AND s.saledate >= #{start}
AND s.saledate <= #{end}
GROUP BY s.drugs_name ORDER BY qty DESC
LIMIT #{limit}

SELECT DATE_FORMAT(s.saledate, '%Y-%m-%d') AS day, COALESCE(SUM(s.num), 0) AS qty, COALESCE(SUM(COALESCE(s.price, 0) * COALESCE(s.num, 0)), 0) AS amount FROM sale s
s.saledate IS NOT NULL
AND s.saledate >= #{start}
AND s.saledate <= #{end}
GROUP BY DATE_FORMAT(s.saledate, '%Y-%m-%d') ORDER BY day ASC

SELECT p.drugs_name AS drugsName, COALESCE(SUM(p.num), 0) AS qty, 0 AS amount FROM purchase p
p.drugs_name IS NOT NULL
AND p.indate >= #{start}
AND p.indate <= #{end}
GROUP BY p.drugs_name ORDER BY qty DESC
LIMIT #{limit}
